function getQuestionsForDifficulty(difficulty) {
    const normalized = String(difficulty || "").trim().toLowerCase();
    return QUESTIONS.filter(question =>
        String(question?.difficulty || "").trim().toLowerCase() === normalized
    );
}

function getQuestionsForCategory(category) {
    if (!category) return QUESTIONS;
    return QUESTIONS.filter(question => question.category === category);
}

function getQuestionCategories() {
    return [...new Set(QUESTIONS.map(question => question.category).filter(Boolean))].sort();
}
